  [STAThread]static int Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);try{string game=Catalog.FindGame();Assets.Resolve(game);if(args.Length>0&&args[0]=="--demo"){string dest=args.Length>1?args[1]:Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Demo");var p=Project.Demo(game);Directory.CreateDirectory(dest);Storage.Save(p,Path.Combine(dest,"Demo.fms.json"));string root=Exporter.Build(p,Path.Combine(dest,"mod"));var errors=Exporter.Parse(root,game);File.WriteAllText(Path.Combine(dest,"build-report.txt"),String.Join("\r\n",errors.Count==0?new[]{"All generated Lua files parsed successfully by Forts LuaPlusC.exe."}:errors.ToArray()));return errors.Count==0?0:1;}if(args.Length>2&&args[0]=="--install-range"){FortsRange.Prepare(Storage.Load(args[1]),args[2],true);return 0;}if(args.Length>2&&args[0]=="--range"){FortsRange.Prepare(Storage.Load(args[1]),args[2],false);return 0;}if(args.Length>2&&args[0]=="--export"){Exporter.Zip(Storage.Load(args[1]),args[2]);return 0;}if(args.Length>1&&args[0]=="--install"){var p=Storage.Load(args[1]);Exporter.Install(p);Storage.Save(p,args[1]);return 0;}Application.Run(new Studio(args.Length>0?Storage.Load(args[0]):null));return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"startup-error.txt"),ex.ToString());if(args.Length==0)UiDialogs.Show(ex.Message,"Forts Mod Studio",MessageBoxButtons.OK,MessageBoxIcon.Error);return 1;}}
 }
