  void Open(){Safe(()=>{using(var dlg=new OpenFileDialog{Filter="Проект Forts Studio|*.json|Все файлы|*.*"}){if(UiDialogs.Show(dlg,this)!=DialogResult.OK)return;var p=Storage.Load(dlg.FileName);project=p;ResetNavigation();projectPath=dlg.FileName;Assets.Resolve(p.GameRoot);Mark();Switch("materials");}});}
  void Save(){Safe(()=>{using(var dlg=new SaveFileDialog{Filter="Проект Forts Studio|*.fms.json",FileName=project.Folder+".fms.json"}){if(projectPath.Length==0){if(UiDialogs.Show(dlg,this)!=DialogResult.OK)return;projectPath=dlg.FileName;}Storage.Save(project,projectPath);status.Text="Проект сохранён: "+projectPath;}});}
  void Zip(){Safe(()=>{using(var dlg=new SaveFileDialog{Filter="Мод Forts|*.zip",FileName=project.Folder+".zip"}){if(UiDialogs.Show(dlg,this)!=DialogResult.OK)return;Exporter.Zip(project,dlg.FileName);status.Text="ZIP создан и проверен игровым анализатором Lua: "+dlg.FileName;UiDialogs.Show("ZIP готов. Распакуйте целиком в Forts/data/mods/ или используйте «Установить в Forts».","Экспорт завершён");}});}
  void Install(){Safe(()=>{string folder=Exporter.Install(project);Mark();status.Text="Установлено: "+folder;UiDialogs.Show("Мод установлен:\n"+folder+"\n\nПерезапустите Forts → Песочница → карта → вкладка «Игрок».\nИщите: "+project.NameRu+"\nСбросьте поисковую строку и фильтры.\n\nПредыдущая версия этого проекта сохранена в .fms-history. Другие моды не изменены.","Установка завершена",MessageBoxButtons.OK,MessageBoxIcon.Information);});}
  void ShowChecks(){Safe(()=>{selected=null;var f=Begin("Проверка и журнал","Синтаксис проверяет штатный анализатор вашей установленной Forts.");var issues=Exporter.Validate(project);string result="";if(issues.Count==0){string tmp=Path.Combine(Path.GetDirectoryName(autosavePath),"checks",Guid.NewGuid().ToString("N"));string root=Exporter.Build(project,tmp);issues=Exporter.Parse(root,project.GameRoot);result="Сборка: "+root+"\r\nLua-файлов: "+Directory.GetFiles(root,"*.lua",SearchOption.AllDirectories).Length+"\r\n"+(issues.Count==0?"Игровой анализатор: ошибок синтаксиса нет.":String.Join("\r\n",issues));}else result=String.Join("\r\n",issues);var t=Theme.TextBox(result+"\r\n\r\n"+Exporter.LogReport(project));t.Multiline=true;t.ReadOnly=true;t.ScrollBars=ScrollBars.Both;t.WordWrap=false;t.Width=490;t.Height=610;t.Font=new Font("Consolas",9);f.Controls.Add(t);ClearUi(right);var help=Theme.Flow(true);right.Controls.Add(help);help.Controls.Add(Theme.Label("Как читать проверку",18,true));help.Controls.Add(Theme.Label("Проверка синтаксиса подтверждает, что Lua разобран игрой. Загрузка проекта подтверждается строкой FMS_LOADED в журнале после запуска матча. Баланс, физику и взаимодействие с другими модами нужно проверять в Forts.",10));help.Controls.Add(Theme.Button("Обновить журнал",ShowChecks));help.Controls.Add(Theme.Button("Установить в Forts",Install,true));});}
