 public class Choice {public string Key,Label;public Choice(string key,string label){Key=key;Label=label;}public override string ToString(){return UiText.Get(Label);}}
 public class PuzzlePanel:Panel {Color color;public bool Hat;public PuzzlePanel(Color c){color=c;DoubleBuffered=true;BackColor=Theme.Card;}protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;int w=Width-1,h=Height-1;using(var path=new GraphicsPath()){path.AddLines(new[]{new Point(0,10),new Point(18,10),new Point(26,Hat?0:18),new Point(53,Hat?0:18),new Point(61,10),new Point(w-9,10)});path.AddArc(w-18,10,18,18,270,90);path.AddLine(w,19,w,h-15);path.AddArc(w-18,h-29,18,18,0,90);path.AddLines(new[]{new Point(w-9,h-11),new Point(61,h-11),new Point(53,h),new Point(26,h),new Point(18,h-11),new Point(9,h-11)});path.AddArc(0,h-29,18,18,90,90);path.AddLine(0,h-20,0,10);path.CloseFigure();using(var b=new SolidBrush(color))e.Graphics.FillPath(b,path);using(var p=new Pen(Color.FromArgb(60,255,255,255)))e.Graphics.DrawPath(p,path);}}}
